"use strict";(globalThis.webpackChunkgrc||=[]).push([[47761],{21486(e){e.exports=JSON.parse('{"citeKey":"yan2024aceminer","slug":"yan-2024-aceminer-c390","title":"AceMiner: Accelerating Graph Pattern Matching using PIM with Optimized Cache System","authors":["L. Yan","X. Lu","X. Chen","S. Xu","X. Zou","Y. Han","X.-H. Sun"],"venue":"The 2024 IEEE 42nd International Conference on Computer Design (ICCD\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/iccd63220.2024.00091","abstract":"Graph pattern matching (GPM), a critical algorithm for discovering specific patterns within complex structures, is becoming increasingly important in the data-driven world. GPM applications are memory-bound and can be accelerated by memory-centric computing systems, such as processing-in-memory (PIM). However, there are three primary challenges when it comes to accelerating GPM applications with PIM: (1) difficulty in utilizing locality, (2) heavy data movement, and (3) heavy comparison overhead due to pruning. To address these challenges, we propose AceMiner, a framework to accelerate GPM applications with a software and hardware co-design perspective using PIM. In AceMiner, we embed hybridCache, a novel in-DRAM cache system with lower access latency and optimized replacement policy, to leverage the potential locality and reduce data movement in PIM. Additionally, we introduce a comparison unit to address the huge pruning overhead. Experimental results show that AceMiner outperforms the state-of-the-art, achieving speedups of 40.2% and 13.3% over NDMiner and DIMMining respectively, with less energy consumption and design overhead.","hasAbstract":true,"lede":"To address these challenges, we propose AceMiner, a framework to accelerate GPM applications with a software and hardware co-design perspective using PIM.","links":{"pdf":"https://grc.iit.edu/papers/2024/yan-2024-aceminer-c390.pdf","slides":"https://grc.iit.edu/papers/2024/yan-2024-aceminer-c390-slides.pdf"},"tags":["Graph Pattern Matching","Processing-in-Memory","Cache System"],"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["unimcc"],"memberAuthors":["lu-xiaoyang","sun-xian-he"]}')}}]);